"use client";

import { useState } from "react";
import { useParams } from "next/navigation";
import { useBoards } from "@/lib/boards/useBoards";
import { ProjectPin } from "./ProjectPin";
import { CreateBoardModal } from "./CreateBoardModal";

export function BulletinBoard() {
  const { boards, loading } = useBoards();
  const params = useParams<{ boardId?: string }>();
  const selectedId = params?.boardId;
  const [showCreate, setShowCreate] = useState(false);

  return (
    <div className="relative mx-auto max-w-6xl px-6 py-10 sm:px-10">
      <div className="mb-8 flex items-end justify-between">
        <h1 className="font-serif text-4xl text-stone-900 sm:text-5xl">
          Your worlds, all in one place.
        </h1>
        <button
          onClick={() => setShowCreate(true)}
          className="flex items-center gap-2 rounded-full bg-stone-900 px-4 py-2 text-sm font-medium text-white shadow-md transition hover:bg-stone-700"
        >
          <span className="text-lg leading-none">+</span>
          New board
        </button>
      </div>

      <div className="cork-texture relative rounded-2xl border-8 border-[#5b3a24] p-8 sm:p-12">
        {loading ? (
          <p className="py-16 text-center text-stone-500">Loading your boards…</p>
        ) : boards.length === 0 ? (
          <EmptyState onCreate={() => setShowCreate(true)} />
        ) : (
          <div className="flex flex-wrap gap-8">
            {boards.map((board) =>
              // While this board is the "selected" one (we're on /boards/[id]),
              // leave its spot empty — BoardDetail renders a matching layoutId
              // so Framer Motion can morph the pin into the full panel instead
              // of two copies existing at once.
              board.id === selectedId ? (
                <div key={board.id} className="w-64 shrink-0" />
              ) : (
                <ProjectPin key={board.id} board={board} />
              )
            )}
          </div>
        )}
      </div>

      {showCreate && <CreateBoardModal onClose={() => setShowCreate(false)} />}
    </div>
  );
}

function EmptyState({ onCreate }: { onCreate: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
      <p className="font-serif text-xl text-stone-700">
        Pin your first inspiration.
      </p>
      <p className="max-w-sm text-sm text-stone-500">
        Upload a few photos that capture a look you love — a room, an outfit,
        a place. We'll turn it into a vibe you can shop from.
      </p>
      <button
        onClick={onCreate}
        className="mt-2 rounded-full bg-stone-900 px-5 py-2 text-sm font-medium text-white"
      >
        Create a board
      </button>
    </div>
  );
}
